"""Tests for Bond calculations — Financial Models"""

from src.tools.bonds import (
    bond_price,
    current_yield,
    yield_to_maturity,
    bond_duration,
    bond_convexity,
    zero_coupon_bond_price,
)


class TestBondPrice:
    def test_premium_bond(self):
        # Coupon > YTM → premium
        result = bond_price(1000, 10, 8, 5, 2)
        assert result["bond_price"] > 1000
        assert "Premium" in result["premium_or_discount"]

    def test_discount_bond(self):
        # Coupon < YTM → discount
        result = bond_price(1000, 8, 10, 5, 2)
        assert result["bond_price"] < 1000
        assert "Discount" in result["premium_or_discount"]

    def test_par_bond(self):
        # Coupon = YTM → par
        result = bond_price(1000, 8, 8, 5, 2)
        assert abs(result["bond_price"] - 1000) < 0.01


class TestCurrentYield:
    def test_calculation(self):
        result = current_yield(80, 950)
        assert abs(result["current_yield"] - 8.4211) < 0.01


class TestYTM:
    def test_ytm_calculation(self):
        result = yield_to_maturity(1000, 8, 922.78, 5, 2)
        assert abs(result["ytm"] - 10.0) < 0.1

    def test_ytm_premium_bond(self):
        result = yield_to_maturity(1000, 10, 1081.11, 5, 2)
        assert result["ytm"] < 10  # YTM < coupon for premium


class TestDuration:
    def test_duration_less_than_maturity(self):
        result = bond_duration(1000, 8, 10, 5, 2)
        assert result["macaulay_duration_years"] < 5

    def test_modified_duration(self):
        result = bond_duration(1000, 8, 10, 5, 2)
        assert result["modified_duration"] < result["macaulay_duration_years"]


class TestConvexity:
    def test_convexity_positive(self):
        result = bond_convexity(1000, 8, 10, 5, 2)
        assert result["convexity_years"] > 0


class TestZeroCoupon:
    def test_zero_coupon_discount(self):
        result = zero_coupon_bond_price(1000, 10, 5)
        assert result["price"] < 1000
        assert abs(result["price"] - 620.92) < 1

"""Tests for Debt Management calculations — Financial Models"""

from src.tools.debt import (
    calculate_emi,
    loan_amortization_schedule,
    loan_comparison,
    prepayment_impact,
    invest_vs_prepay,
)


class TestEMI:
    def test_home_loan(self):
        result = calculate_emi(5000000, 8.5, 20)
        assert abs(result["emi"] - 43391.16) < 1

    def test_total_interest(self):
        result = calculate_emi(5000000, 8.5, 20)
        assert result["total_interest"] > result["principal"]

    def test_zero_rate(self):
        result = calculate_emi(1200000, 0, 10)
        assert result["emi"] == 10000.0

    def test_short_tenure(self):
        result = calculate_emi(100000, 12, 1)
        assert result["emi"] > 0
        assert result["tenure_months"] == 12


class TestAmortization:
    def test_schedule_generated(self):
        result = loan_amortization_schedule(1000000, 10, 5)
        assert len(result["schedule"]) > 0
        assert result["schedule"][0]["month"] == 1

    def test_balance_decreases(self):
        result = loan_amortization_schedule(1000000, 10, 5)
        balances = [r["balance"] for r in result["schedule"]]
        # First balance should be less than principal
        assert balances[0] < 1000000

    def test_final_balance_zero(self):
        result = loan_amortization_schedule(1000000, 10, 5)
        last = result["schedule"][-1]
        assert last["balance"] == 0


class TestLoanComparison:
    def test_comparison(self):
        loans = [
            {
                "principal": 5000000,
                "annual_rate": 8.5,
                "tenure_years": 20,
                "name": "Bank A",
            },
            {
                "principal": 5000000,
                "annual_rate": 9.0,
                "tenure_years": 20,
                "name": "Bank B",
            },
        ]
        result = loan_comparison(loans)
        assert result["comparison"][0]["name"] == "Bank A"  # Lower rate = lower cost


class TestPrepayment:
    def test_prepayment_saves(self):
        result = prepayment_impact(5000000, 8.5, 20, 5000)
        assert result["interest_saved"] > 0
        assert result["months_saved"] > 0


class TestInvestVsPrepay:
    def test_high_return_invest(self):
        result = invest_vs_prepay(8.5, 15, 30, True)
        assert "INVEST" in result["recommendation"]

    def test_low_return_prepay(self):
        result = invest_vs_prepay(12, 8, 30, False)
        assert "PREPAY" in result["recommendation"]

"""Tests for Portfolio Analytics — Financial Models-16"""

from src.tools.portfolio import (
    portfolio_expected_return,
    portfolio_risk,
    two_asset_portfolio,
    capm,
    sharpe_ratio,
    treynor_ratio,
    jensens_alpha,
    information_ratio,
    sortino_ratio,
    asset_allocation_suggestion,
    portfolio_rebalancing,
)


class TestPortfolioReturn:
    def test_expected_return(self):
        result = portfolio_expected_return([0.6, 0.4], [15, 8])
        assert abs(result["portfolio_expected_return"] - 12.2) < 0.01

    def test_dimension_mismatch(self):
        result = portfolio_expected_return([0.6], [15, 8])
        assert "error" in result


class TestPortfolioRisk:
    def test_two_asset_risk(self):
        result = portfolio_risk([0.6, 0.4], [20, 10], [[1, 0.3], [0.3, 1]])
        assert result["portfolio_std_dev"] > 0
        assert result["diversification_benefit"] > 0

    def test_perfect_correlation(self):
        result = portfolio_risk([0.5, 0.5], [10, 10], [[1, 1], [1, 1]])
        # With perfect correlation, diversification benefit = 0
        assert abs(result["diversification_benefit"]) < 0.01


class TestTwoAsset:
    def test_basic(self):
        result = two_asset_portfolio(0.6, 15, 20, 8, 10, 0.3)
        assert result["portfolio_return"] > 0
        assert result["portfolio_risk"] > 0
        assert "minimum_variance_portfolio" in result


class TestCAPM:
    def test_capm(self):
        result = capm(6, 1.2, 15)
        assert abs(result["expected_return"] - 16.8) < 0.01

    def test_defensive_beta(self):
        result = capm(6, 0.8, 15)
        assert "Defensive" in result["beta_interpretation"]


class TestSharpeRatio:
    def test_good_sharpe(self):
        result = sharpe_ratio(15, 6, 8)
        assert result["sharpe_ratio"] == 1.125
        assert "Excellent" in result["interpretation"]

    def test_poor_sharpe(self):
        result = sharpe_ratio(5, 6, 8)
        assert result["sharpe_ratio"] < 0


class TestTreynorRatio:
    def test_treynor(self):
        result = treynor_ratio(15, 6, 1.2)
        assert abs(result["treynor_ratio"] - 7.5) < 0.01


class TestJensensAlpha:
    def test_positive_alpha(self):
        result = jensens_alpha(18, 6, 1.2, 15)
        assert result["jensens_alpha"] > 0

    def test_negative_alpha(self):
        result = jensens_alpha(10, 6, 1.2, 15)
        assert result["jensens_alpha"] < 0


class TestInformationRatio:
    def test_ir(self):
        result = information_ratio(15, 12, 4)
        assert result["information_ratio"] == 0.75


class TestSortinoRatio:
    def test_sortino(self):
        result = sortino_ratio(15, 6, 5)
        assert result["sortino_ratio"] == 1.8


class TestAssetAllocation:
    def test_young_aggressive(self):
        result = asset_allocation_suggestion(25, "aggressive", 20)
        assert result["recommended_allocation"]["equity"] >= 70

    def test_old_conservative(self):
        result = asset_allocation_suggestion(60, "conservative", 5)
        assert result["recommended_allocation"]["equity"] <= 30


class TestRebalancing:
    def test_rebalance(self):
        result = portfolio_rebalancing(
            {"equity": 60, "debt": 30, "gold": 10},
            {"equity": 700000, "debt": 250000, "gold": 50000},
        )
        assert len(result["trades"]) == 3
        assert result["total_portfolio_value"] == 1000000

